func (s SessionServiceServer) Patch(ctx context.Context, req *rove.SessionPatchRequest) (*rove.Session, error) {
	doc, err := ormpatch.FromPatchRequest(sessionOrmEntity, req.ProtoReflect(), nil)
	if err != nil {
		if _, ok := status.FromError(err); ok {
			return nil, err
		}
		if errors.Is(err, ormpatch.ErrRequestLayout) {
			return nil, status.Errorf(codes.Internal, "%s", err)
		}
		if errors.Is(err, ormpatch.ErrUnsupported) {
			return nil, status.Errorf(codes.Unimplemented, "%s", err)
		}
		return nil, status.Errorf(codes.InvalidArgument, "%s", err)
	}

	return s.apply(ctx, req.GetRef(), doc, rove.SessionService_Patch_FullMethodName)
}

func SessionGetKey(ctx context.Context, db *ent.Client, ref *rove.SessionRef) (uuid.UUID, error) {
	var z uuid.UUID
	if ref.HasId() {
		if v, err := entuuid.FromBytes(ref.GetId()); err != nil {
			return z, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return v, nil
		}
	}

	p, err := SessionPick(ref)
	if err != nil {
		return z, err
	}

	v, err := db.Session.Query().Where(p).OnlyId(ctx)
	if err != nil {
		if ent.IsNotFound(err) {
			return z, status.Error(codes.NotFound, "Session not found")
		}
		return z, err
	}

	return v, nil
}

var sessionOrmEntity = ormpatch.MustEntityOf(rove.File_rove_org_proto, "Session")

var sessionPatchColumns = entpatch.Columns{
	1: session.FieldId, 8: session.FieldAccount, 9: session.FieldSecret, 10: session.FieldGrant, 11: session.FieldDateExpires, 12: session.FieldDateIdle, 13: session.FieldDateUpdated, 14: session.FieldDateErased, 15: session.FieldDateCreated}

func (s SessionServiceServer) Apply(ctx context.Context, req *rove.SessionApplyRequest) (*rove.Session, error) {
	if !req.HasPatch() {
		return nil, status.Errorf(codes.InvalidArgument, "%s", ormpatch.ErrNoPatch)
	}
	return s.apply(ctx, req.GetRef(), req.GetPatch(), rove.SessionService_Apply_FullMethodName)
}

func (s SessionServiceServer) apply(ctx context.Context, ref *rove.SessionRef, doc *patchpb.Patch, by string) (*rove.Session, error) {
	plan := &ormpatch.Plan{Entity: sessionOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(sessionOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, sessionPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := SessionGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &rove.SessionRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, session.IdEQ(k))
	if err != nil {
		return nil, err
	}

	if mod == nil {
		q := st.Db.Session.Query().Where(p)
		if pred != nil {
			q.Where(predicate.Session(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.Session.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Session not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.Session.Update().Where(p)
		if pred != nil {
			q.Where(predicate.Session(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "Session already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "Session: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.Session.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Session not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	if mod != nil {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:    by,
			Key:   k,
			Patch: doc,
		}); err != nil {
			return nil, err
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s SessionServiceServer) Erase(ctx context.Context, req *rove.SessionRef) (*rove.SessionEraseResponse, error) {
	p, err := SessionPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.Session.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &rove.SessionEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = session.And(p, session.IdEQ(v))
	}

	u := st.Db.Session.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  rove.SessionService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &rove.SessionEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// SessionPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a Session is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasSessionWith`, where no narrowing of a Session
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func SessionPick(req *rove.SessionRef) (predicate.Session, error) {
	p, err := pickSession(req)
	if err != nil {
		return nil, err
	}

	return session.And(session.DateErasedIsNil(), p), nil
}

func pickSession(req *rove.SessionRef) (predicate.Session, error) {
	switch req.WhichKey() {
	case rove.SessionRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return session.IdEQ(v), nil
		}
	case rove.SessionRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Session")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
